'use client';

/*
 * Consent preferences (shadcn/ui), "pelure" style — generated by `zeste add --style pelure`, yours to edit.
 * Nothing is pre-checked: a service the user has not chosen is treated as refused.
 * Works with the Base UI and Radix flavors of shadcn/ui.
 */
import { useZeste } from '@zeste/react';
import type { Messages } from '@zeste/services/i18n/types';
import { Button } from '%UI%/button';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '%UI%/dialog';
import { Label } from '%UI%/label';
import { Switch } from '%UI%/switch';

const chunky =
  'border-foreground h-auto rounded-[10px] border-[2.5px] px-[18px] py-2.5 font-bold shadow-[4px_4px_0_var(--foreground)] active:translate-x-[2px] active:translate-y-[2px] active:shadow-[2px_2px_0_var(--foreground)]';

export function CookiePreferences() {
  const zeste = useZeste<Messages>();
  const t = zeste.messages;

  return (
    <Dialog open={zeste.preferencesOpen} onOpenChange={(open) => zeste.setPreferencesOpen(open)}>
      <DialogContent className="border-foreground max-h-[85vh] overflow-y-auto rounded-[14px] border-[3px] shadow-[8px_8px_0_var(--foreground)] ring-0 sm:max-w-lg" showCloseButton={false}>
        <DialogHeader>
          <DialogTitle className="text-2xl font-extrabold tracking-tight">{t.title}</DialogTitle>
          <DialogDescription>{t.disclaimer}</DialogDescription>
        </DialogHeader>

        {zeste.categories.map((category) => (
          <section key={category.key} className="border-foreground grid gap-2 border-t-[2.5px] pt-3" aria-labelledby={`zeste-category-${category.key}`}>
            <h3 id={`zeste-category-${category.key}`} className="font-bold">
              {t.categories[category.key]?.title ?? category.key}
            </h3>
            <p className="text-muted-foreground">{t.categories[category.key]?.details}</p>
            <ul className="grid gap-3 pt-1">
              {category.services.map((service) => (
                <li key={service.key} className="flex items-center justify-between gap-4">
                  <div>
                    <Label htmlFor={`zeste-service-${service.key}`}>{service.name}</Label>
                    {service.privacyUrl && (
                      <a
                        href={service.privacyUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="text-muted-foreground hover:text-foreground block underline underline-offset-2"
                      >
                        {t.privacyUrl}{' '}
                        <span className="sr-only">
                          {service.name} {t.newWindow}
                        </span>
                      </a>
                    )}
                  </div>
                  <Switch
                    id={`zeste-service-${service.key}`}
                    checked={zeste.draft[service.key] ?? false}
                    onCheckedChange={(checked) => zeste.setDraft(service.key, checked)}
                  />
                </li>
              ))}
            </ul>
          </section>
        ))}

        {zeste.exempt.length > 0 && (
          <p className="text-muted-foreground border-foreground border-t-[2.5px] pt-3">
            <span className="text-foreground font-medium">{t.mandatoryTitle}</span> :{' '}
            {zeste.exempt.map((s) => s.name).join(', ')}
          </p>
        )}

        <DialogFooter className="sm:justify-start">
          <Button variant="secondary" className={chunky} {...zeste.actions.denyAll}>
            {t.denyAll}
          </Button>
          <Button variant="secondary" className={chunky} {...zeste.actions.acceptAll}>
            {t.acceptAll}
          </Button>
          <Button className={`${chunky} sm:ml-auto`} {...zeste.actions.savePreferences}>
            {t.save}
          </Button>
        </DialogFooter>

        <Button variant="ghost" size="icon-sm" className="absolute top-4 right-4" aria-label={t.close} onClick={zeste.closePreferences}>
          <span aria-hidden="true">✕</span>
        </Button>
      </DialogContent>
    </Dialog>
  );
}
